SELECT c.id,c.ca_notice_contract_id,c.ca_notice_id,c.contract_no,c.contract_date,c.contract_value::text,c.title,c.lots_caption,c.raw_id,aw.notice_no,aw.state,aw.state_date,aw.raw_id award_raw_id,e.name_display authority,
(SELECT jsonb_agg(jsonb_build_object('id',w.entity_id,'name',we.name_display)) FROM core.contract_winners w JOIN core.entities we ON we.id=w.entity_id WHERE w.contract_id=c.id) winners,
(SELECT jsonb_build_object('endpoint',r.endpoint_version,'external_id',r.external_id,'fetched_at',r.fetched_at,'source_hash',r.content_hash,'notice_no',r.payload->>'noticeNo','procedure_id',r.payload->>'procedureId','errata_no',r.payload->>'errataNo','version_no',r.payload->>'versionNo') FROM raw.raw_documents r WHERE r.id=aw.raw_id) award_raw,
(SELECT jsonb_build_object('endpoint',r.endpoint_version,'external_id',r.external_id,'fetched_at',r.fetched_at,'source_hash',r.content_hash,'item',(SELECT jsonb_build_object('caNoticeContractId',item->>'caNoticeContractId','contractId',item->>'contractId','contractNo',item->>'contractNo','contractDate',item->>'contractDate','contractValue',item->>'contractValue','contractTitle',item->>'contractTitle','lotsCaption',item->>'lotsCaption','hasModifiedVersions',item->>'hasModifiedVersions','modifiedCount',item->>'modifiedCount') FROM jsonb_array_elements(r.payload->'items') item WHERE item->>'caNoticeContractId'=c.ca_notice_contract_id::text LIMIT 1)) FROM raw.raw_documents r WHERE r.id=c.raw_id) contract_raw
FROM core.contracts c JOIN core.awards aw USING(ca_notice_id) JOIN core.entities e ON e.id=aw.authority_entity_id WHERE c.ca_notice_contract_id IN (107819123,108119107,107828300,108117421)
